-- Rifts World Book 33: Northern Gun One - the 28 energy weapons printed 191-204 that the catalog did not hold.
-- 28 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~281-northern-gun-1-weapons-energy.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('ng-35-heavy-laser-pistol', 'NG-35 Heavy Laser Pistol', 'rifts', 'weapon', 4.5, 19500, NULL, '3D6 M.D.', 1, '800 feet (244 m)', '14 shots, 22 with a long E-Clip', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'A big, bulky, high-powered laser pistol built for strong and augmented users; sturdy enough to serve as a cudgel.', 'Rifts World Book 33: Northern Gun One p.191', NULL),
  ('ng-lp25-laser-pulse-submachine-gun', 'NG-LP25 Laser Pulse Submachine-Gun', 'rifts', 'weapon', 4, 19000, NULL, '2D6+1 M.D. per single shot, or 5D6 M.D. per rapid-fire triple shot pulse', 1, '1,000 feet (305 m)', '21 single blasts or 7 pulse bursts per standard (short) E-Clip, or 36 single and 12 burst shots per long E-Clip', 'Each blast or triple pulse counts as one melee attack', NULL, NULL, NULL, 'A light, concealable pulse laser popular in urban markets; standard issue for Ishpeming''s police Crisis Response Officers and a favorite of gangs and Black Market criminals.', 'Rifts World Book 33: Northern Gun One p.192', NULL),
  ('ng-lg6-laser-rifle-and-grenade-launcher', 'NG-LG6 Laser Rifle and Grenade Launcher', 'rifts', 'weapon', 19, 20000, 'Block I 20,000 credits, Block II 22,000 credits; grenades 400 credits each; power pack 70,000 credits', 'Laser 3D6 M.D. per blast; grenade 4D6 M.D. to a blast radius of about 12 feet (3.6 m)', 1, 'Laser 1,600 feet (488 m); grenade launcher 1,100 feet (335 m)', 'Laser: 10 shots standard E-Clip, 20 shots long E-Clip, or 70 shots with power pack (pack weighs 12 lbs/5.4 kg and regenerates 4 blasts per hour). Grenade launcher: four grenades (pump action); reloading takes one melee attack/action', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'An NG-L5 laser rifle mated to a full-size grenade launcher that takes any grenade in NG''s inventory (see the GL-10 for grenade types). Block I weighs 19 lbs (8.6 kg), Block II 15 lbs (6.8 kg).', 'Rifts World Book 33: Northern Gun One p.193', NULL),
  ('ng-sr3-marksman-collapsible-sniper-laser-rifle', 'NG-SR3 "Marksman" Collapsible Sniper Laser Rifle', 'rifts', 'weapon', 8, 32000, NULL, '3D6 M.D. medium setting or 4D6 M.D. high intensity setting; S.D.C. setting 1D6x10 S.D.C.', 1, '2,400 feet (731.5 m)', 'Standard E-Clip: 5 high-intensity or 10 medium M.D. shots; an S.D.C. shot drains one fifth of a medium shot. Long E-Clips double the payload', 'Each blast counts as one melee attack', NULL, NULL, NULL, 'A compact precision laser rifle that breaks down into five parts (one melee round) to fit a briefcase or bag. Comes with a telescopic sight and passive nightvision scope (2,000 foot/610 m range). +2 to strike on an Aimed shot. Banned for sale in the Coalition and Free Quebec.', 'Rifts World Book 33: Northern Gun One p.193', NULL),
  ('ng-sl20-sniper-laser-rifle', 'NG-SL20 Sniper Laser Rifle', 'rifts', 'weapon', 10, 50000, NULL, 'Laser 4D6 M.D.; ion blaster 3D6 M.D.', 1, 'Laser 3,000 feet (914 m); ion blaster 1,000 feet (305 m)', '5 laser shots or 10 ion blasts', 'Each laser shot requires two melee actions to aim and shoot; each ion blast counts as one melee action/attack', NULL, NULL, NULL, 'A knock-off of the Triax TX-SL12 with laser targeting and self-balancing, plus an ion blaster for close quarters. +3 to strike with the laser, only +1 with the ion blaster.', 'Rifts World Book 33: Northern Gun One p.194', NULL),
  ('ng-ssl20-super-sniper-laser-rifle', 'NG-SSL20 Super-Sniper Laser Rifle', 'rifts', 'weapon', 10, 60000, NULL, '6D6+6 M.D.; single shot only', 1, '2,000 feet (610 m)', '6 laser blasts per short E-Clip or 12 per long E-Clip', 'Each shot counts as two melee attacks', NULL, NULL, NULL, 'A large, high-powered sniper laser whose sensitive optics need two melee attacks/actions for an Aimed shot. +1 to strike on Aimed attacks; -1 to strike on anything other than an Aimed shot.', 'Rifts World Book 33: Northern Gun One p.194', NULL),
  ('ng-se3-laser-emergency-side-arm', 'NG-SE3 Laser Emergency Side Arm', 'rifts', 'weapon', 0.5, 6000, NULL, '1D4+1 M.D.', 1, '600 feet (183 m)', '20 shots per standard E-Clip', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'Seasnake series blue-green laser: a small backup pistol for sailors, pilots and divers. Fires underwater; the range applies both underwater and in an atmosphere.', 'Rifts World Book 33: Northern Gun One p.195', NULL),
  ('ng-se5-laser-pistol', 'NG-SE5 Laser Pistol', 'rifts', 'weapon', 1.5, 7500, NULL, '2D4+2 M.D.', 1, '800 feet (244 m)', '24 shots per standard E-Clip, 38 with a long E-Clip', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'Seasnake series blue-green laser: the line''s standard light, reliable handgun. Fires underwater; the range applies both underwater and in an atmosphere.', 'Rifts World Book 33: Northern Gun One p.195', NULL),
  ('ng-se9-sharpshooter-laser-pistol', 'NG-SE9 Sharpshooter Laser Pistol', 'rifts', 'weapon', 2.5, 15000, 'Includes a telescopic scope with passive nightvision (3,000 feet/914 m) and laser distancer (1,500 feet/457 m)', '3D4+3 M.D.', 1, '1,000 feet (305 m)', '20 shots, 36 with a long E-Clip', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'Seasnake series blue-green laser: an SE5 with a longer barrel and a standard scope, favored by marksmen, hunters, pirates and aquatic D-Bees. Fires underwater; the range applies both underwater and in an atmosphere.', 'Rifts World Book 33: Northern Gun One p.195', NULL),
  ('ng-se14-laser-burst-pistol', 'NG-SE14 Laser Burst Pistol', 'rifts', 'weapon', 4, 17000, NULL, '1D6+4 M.D. single blast or 2D6+6 M.D. dual burst', 1, '800 feet (244 m)', '20 single shots or 10 bursts per standard E-Clip; 32 single or 16 dual blasts per long E-Clip', 'Each shot or burst counts as one melee attack', NULL, NULL, NULL, 'Seasnake series blue-green laser: a pistol-submachine-gun for boarding parties that can fire a double-tap. Fires underwater; the range applies both underwater and in an atmosphere.', 'Rifts World Book 33: Northern Gun One p.196', NULL),
  ('ng-se17-laser-carbine', 'NG-SE17 Laser Carbine', 'rifts', 'weapon', 9, 20000, NULL, '3D6 M.D.', 1, '1,500 feet (457 m)', '17 shots per standard E-Clip or 28 per long E-Clip', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'Seasnake series blue-green laser: a compact carbine for boarding actions and lifeboat stowage. Fires underwater; the range applies both underwater and in an atmosphere.', 'Rifts World Book 33: Northern Gun One p.196', NULL),
  ('ng-se20-laser-rifle', 'NG-SE20 Laser Rifle', 'rifts', 'weapon', 12, 25000, NULL, '3D6+4 M.D.', 1, '1,800 feet (549 m)', '15 shots per standard E-Clip or 25 per long E-Clip', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'Seasnake series blue-green laser: the line''s heaviest weapon, a battle rifle sturdy enough for melee. Fires underwater; the range applies both underwater and in an atmosphere.', 'Rifts World Book 33: Northern Gun One p.196', NULL),
  ('ng-uv1-solar-powered-mini-laser', 'NG-UV1 Solar Powered Mini-Laser', 'rifts', 'weapon', 0.8, 12000, NULL, '1D6 M.D.', 1, '300 feet (91.5 m)', '12 solar charges, one shot each; two hours of direct sunlight recharges one blast, and diffused sunlight does not charge it. Can also use standard E-Clips (22 blasts)', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'A small solar-powered pistol with a flip-up panel; the grip folds back into a tube for storage, at -1 to strike.', 'Rifts World Book 33: Northern Gun One p.197', NULL),
  ('ng-uv4-solar-powered-laser-pistol', 'NG-UV4 Solar Powered Laser Pistol', 'rifts', 'weapon', 3.8, 20000, NULL, '2D4+1 M.D.', 1, '600 feet (183 m)', '16 solar charges, one shot each; three hours of direct sunlight recharges each shot, and diffused sunlight does not charge it. Can also use standard E-Clips (20 blasts)', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'A full-sized solar-powered pistol, bulky with its solar panel hood.', 'Rifts World Book 33: Northern Gun One p.197', NULL),
  ('ng-uv7-solar-powered-laser-rifle', 'NG-UV7 Solar Powered Laser Rifle', 'rifts', 'weapon', 7.5, 30000, NULL, '2D6 M.D.', 1, '1,200 feet (366 m)', '18 solar charges, one shot each; four hours of direct sunlight recharges each shot. Can also use standard E-Clips (20 blasts)', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'A solar-powered survival rifle; the panel clips on top or can be worn on the shoulder or back on an extendable M.D. cord.', 'Rifts World Book 33: Northern Gun One p.198', NULL),
  ('ng-56-light-ion-pistol', 'NG-56 Light Ion Pistol', 'rifts', 'weapon', 3, 10000, 'List price 10,000 credits, but on sale at 5,000 so often that most people think of that as the list price; power pack 60,000 credits', '2D6 M.D.', 1, '400 feet (122 m)', '6 shots per standard E-Clip, 12 per long E-Clip, or 42 with a power pack (pack weighs 3 lbs/1.4 kg and recharges 4 blasts per hour)', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'An older, light ion side arm that burns through E-Clips quickly. Block I weighs 3 lbs (1.4 kg), Block II 2.5 lbs (1.1 kg).', 'Rifts World Book 33: Northern Gun One p.198-199', NULL),
  ('ng-59-ion-pistol-and-grenade-launcher', 'NG-59 Ion Pistol and Grenade Launcher', 'rifts', 'weapon', 3.5, 15000, 'Grenades 400 credits apiece or 3,800 a dozen', 'Ion 2D6 M.D.; grenade 2D6 M.D. to a blast area of six feet (1.8 m)', 1, 'Ion 400 feet (122 m); grenade launcher 500 feet (152 m)', '20 shots per standard E-Clip, 30 per long E-Clip; the grenade launcher holds one grenade', 'Each shot or grenade counts as one melee attack; reloading the grenade launcher requires one melee action', NULL, NULL, NULL, 'A variant of the NG-56 with a single-shot grenade launcher that fires almost any rifle grenade; law enforcement often loads smoke or tear gas. The page also says a grenade takes two melee actions to reload.', 'Rifts World Book 33: Northern Gun One p.199', NULL),
  ('ng-ir5-ion-rifle', 'NG-IR5 Ion Rifle', 'rifts', 'weapon', 11, 24000, NULL, 'Two settings, 2D6 or 4D6 M.D.', 1, '2,000 feet (610 m)', '20 shots per standard E-Clip at the low setting, 11 at the high; 36 and 15 with a long E-Clip', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'A rifle version of the NG-57 with its dual settings and the ability to fire into and under water; popular on the Great Lakes against lake monsters.', 'Rifts World Book 33: Northern Gun One p.199-200', NULL),
  ('ng-i26-ion-scatter-rifle', 'NG-I26 Ion Scatter Rifle', 'rifts', 'weapon', 24, 45000, NULL, '2D6+3 M.D. to everyone within a 6 foot (1.8 m) radius of the intended target and not behind cover', 1, '400 feet (122 m)', '9 shots per two standard E-Clips, 16 with two long E-Clips', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'Ion Scatter series: a battlefield rifle spreading ion charges across a horizontal plane, for trenches and massed attackers. -2 to strike even on aimed shots. Range and damage are halved underwater.', 'Rifts World Book 33: Northern Gun One p.200-201', NULL),
  ('ng-i8-light-ion-scattergun', 'NG-I8 Light Ion Scattergun', 'rifts', 'weapon', 5, 25000, NULL, '1D6 M.D. to everyone within a 4 foot (1.2 m) radius of the intended target and not behind cover', 1, '100 feet (30.5 m)', '10 shots per standard E-Clip, 18 with a long E-Clip', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'Ion Scatter series: a five-barrel ''pistol'' scattergun, really a submachine-gun, for clearing rooms. -2 to strike even on aimed shots. Range and damage are halved underwater.', 'Rifts World Book 33: Northern Gun One p.200', NULL),
  ('ng-i13-medium-ion-scattergun', 'NG-I13 Medium Ion Scattergun', 'rifts', 'weapon', 9, 35000, NULL, '2D6 M.D. to everyone within a 4 foot (1.2 m) radius of the intended target and not behind cover', 1, '200 feet (61 m)', '10 shots per two standard E-Clips, 18 with two long E-Clips', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'Ion Scatter series: the shotgun version, powered by two E-Clips. -1 to strike even on aimed shots and with a forward grip. Range and damage are halved underwater.', 'Rifts World Book 33: Northern Gun One p.200', NULL),
  ('ng-pb713-particle-beam-pistol', 'NG-PB713 Particle Beam Pistol', 'rifts', 'weapon', 6, 40000, 'Double to triple outside of Northern Gun, even at NG stores away from Upper Michigan; poor availability', '5D6 M.D. per blast; a Critical Strike on a Natural 19 or 20 does 50% more damage. Vampires, Werebeasts and mummies are impervious', 1, '300 feet (91.5 m)', '10 shots per standard short E-Clip, 16 with a long E-Clip', 'Single shot only; each shot counts as a melee attack', NULL, NULL, NULL, 'A particle beam small enough to be a pistol, and NG''s hottest-selling new handgun.', 'Rifts World Book 33: Northern Gun One p.201', NULL),
  ('ng-p5-light-particle-beam-rifle', 'NG-P5 Light Particle Beam Rifle', 'rifts', 'weapon', 14, 28000, NULL, '5D6 M.D.; a Critical Strike on a Natural 19 or 20 does 50% more damage. Vampires, Werebeasts and mummies are impervious', 1, '1,200 feet (365 m)', '10 shots per standard short E-Clip, 16 with a long E-Clip', 'Single shot only; each shot counts as a melee attack', NULL, NULL, NULL, 'A lighter, more modern particle beam rifle based on the NG-P7 and the NG-45LP, with better ammunition capacity.', 'Rifts World Book 33: Northern Gun One p.201', NULL),
  ('ng-p9-heavy-particle-beam-rifle', 'NG-P9 Heavy Particle Beam Rifle', 'rifts', 'weapon', 12, 45000, 'Double to triple outside of Northern Gun, even at NG stores away from Upper Michigan; poor availability', '1D4x10 M.D. per blast; a Critical Strike on a Natural 19 or 20 does 50% more damage. Vampires, Werebeasts and mummies are impervious', 1, '1,600 feet (488 m)', '6 shots per standard E-Clip or 9 with a long E-Clip', 'Single shot only; each shot counts as a melee attack', NULL, NULL, NULL, 'The big brother of the P5 and P7, often outshone by Coalition, Naruni and Triax equivalents. Laser targeting standard: +1 to strike on aimed shots.', 'Rifts World Book 33: Northern Gun One p.202', NULL),
  ('ng-p85-personal-particle-beam-cannon', 'NG-P85 Personal Particle Beam Cannon', 'rifts', 'weapon', 61, 75000, 'Includes the apparatus for attaching it to the back and shoulders', '1D4x10+4 M.D. per blast; a Critical Strike on a Natural 19 or 20 does 50% more damage. Vampires, Werebeasts and mummies are impervious', 1, '1,800 feet (549 m)', '4 shots per short E-Clip, 7 per long E-Clip, 30 blasts with an NG power pack', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'A shoulder-mounted particle beam cannon for Combat Cyborgs and power armor. Mounted: -1 to dodge, running speed -10%, jet-pack or power armor flying speed -20%; needs W.P. Heavy Weapons for strike bonuses. Wired into the wearer''s own nuclear supply: a further -10% speed, -1 to dodge and -1 attack per melee round. One per wearer; not every armor or cyborg can take it.', 'Rifts World Book 33: Northern Gun One p.203', NULL),
  ('ng-e4-plasma-ejector', 'NG-E4 Plasma Ejector', 'rifts', 'weapon', 20, 30000, NULL, '6D6 M.D.', 1, '1,600 feet (488 m)', '10 shots per standard E-Clip or 20 per long E-Clip', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'A man-portable plasma rifle whose internals resemble the Coalition''s old C-27 Plasma Cannon. Block I weighs 20 lbs (9 kg), Block II 16 lbs (7.2 kg).', 'Rifts World Book 33: Northern Gun One p.203', NULL),
  ('ng-e12-heavy-plasma-ejector', 'NG-E12 Heavy Plasma Ejector', 'rifts', 'weapon', 30, 80000, 'Power pack 80,000 credits', '1D6x10 M.D.', 1, '2,000 feet (610 m)', '6 shots standard E-Clip, 12 long E-Clip, or 42 with a power pack (pack weighs 20 lbs/9 kg and regenerates 4 blasts per hour)', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'An enlarged E4 for emplacements and vehicles, with a rifle version for cyborgs and power armor; too heavy for unaugmented humans. Weighs 30 lbs (12.5 kg) on an E-Clip, 50 lbs (22.5 kg) with a power pack.', 'Rifts World Book 33: Northern Gun One p.204', NULL),
  ('ng-e15-pulse-plasma-ejector', 'NG-E15 Pulse Plasma Ejector', 'rifts', 'weapon', 50, 62000, 'Power pack 30,000 credits; it can be recharged up to 20 times at 10,000 credits each', '5D6 M.D. per single shot or 2D4x10 M.D. per triple pulse burst', 1, '1,600 feet (488 m)', 'Power pack: 48 single shots or 16 triple pulses. Long E-Clip: 12 single or 4 pulse. Standard E-Clip: 6 single or 2 pulse', 'Each single blast or triple pulse counts as one melee attack', NULL, NULL, NULL, 'A heavy pulse plasma weapon for augmented troops and strong D-Bees: 50 lbs (22.5 kg) plus a 20 lb (9 kg) power pack. -2 to strike even with Supernatural, Robot or Bionic P.S. or human P.S. 25+, -7 with less strength, -1 even on a tripod or vehicle.', 'Rifts World Book 33: Northern Gun One p.204', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 28 gear rows are in' AS assertion, count(*) AS got, 28 AS want
  FROM gear WHERE slug IN ('ng-35-heavy-laser-pistol', 'ng-lp25-laser-pulse-submachine-gun', 'ng-lg6-laser-rifle-and-grenade-launcher', 'ng-sr3-marksman-collapsible-sniper-laser-rifle', 'ng-sl20-sniper-laser-rifle', 'ng-ssl20-super-sniper-laser-rifle', 'ng-se3-laser-emergency-side-arm', 'ng-se5-laser-pistol', 'ng-se9-sharpshooter-laser-pistol', 'ng-se14-laser-burst-pistol', 'ng-se17-laser-carbine', 'ng-se20-laser-rifle', 'ng-uv1-solar-powered-mini-laser', 'ng-uv4-solar-powered-laser-pistol', 'ng-uv7-solar-powered-laser-rifle', 'ng-56-light-ion-pistol', 'ng-59-ion-pistol-and-grenade-launcher', 'ng-ir5-ion-rifle', 'ng-i26-ion-scatter-rifle', 'ng-i8-light-ion-scattergun', 'ng-i13-medium-ion-scattergun', 'ng-pb713-particle-beam-pistol', 'ng-p5-light-particle-beam-rifle', 'ng-p9-heavy-particle-beam-rifle', 'ng-p85-personal-particle-beam-cannon', 'ng-e4-plasma-ejector', 'ng-e12-heavy-plasma-ejector', 'ng-e15-pulse-plasma-ejector') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~281-northern-gun-1-weapons-energy.sql');
